package tlgen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strings"
)

// Options controls code emission.
type Options struct {
	Package   string // generated package name ("gen")
	SchemaSHA [2]string
	Layer     int
}

type codegen struct {
	opt    *Options
	sch    *Schema
	byName map[string]*Def
	out    *bytes.Buffer
}

// Generate renders all generated files. The returned map is keyed by file
// name; contents are gofmt'd and fully deterministic for a given schema.
func Generate(sch *Schema, opt *Options) (map[string][]byte, error) {
	if opt.Package == "" {
		opt.Package = "gen"
	}
	byName := map[string]*Def{}
	for _, d := range append(append([]*Def{}, sch.Types...), sch.Functions...) {
		byName[d.Qualified()] = d
	}
	g := &codegen{opt: opt, sch: sch, byName: byName}

	files := map[string][]byte{}

	// Abstract interfaces.
	g.out = &bytes.Buffer{}
	if err := g.genInterfaces(); err != nil {
		return nil, err
	}
	files["interfaces.go"] = g.finish()

	// Common runtime glue: layer, dispatch, helpers.
	g.out = &bytes.Buffer{}
	if err := g.genCommon(); err != nil {
		return nil, err
	}
	files["common.go"] = g.finish()

	// Types and functions grouped by namespace, in first-seen order.
	emit := func(defs []*Def, prefix string) error {
		groups := map[string][]*Def{}
		var order []string
		for _, d := range defs {
			key := d.Namespace
			if _, seen := groups[key]; !seen {
				order = append(order, key)
			}
			groups[key] = append(groups[key], d)
		}
		for _, ns := range order {
			g.out = &bytes.Buffer{}
			for _, d := range groups[ns] {
				if err := g.genDef(d); err != nil {
					return err
				}
			}
			name := fmt.Sprintf("%s_%s.go", prefix, nsFileName(ns))
			files[name] = g.finish()
		}
		return nil
	}
	if err := emit(sch.Types, "types"); err != nil {
		return nil, err
	}
	if err := emit(sch.Functions, "functions"); err != nil {
		return nil, err
	}
	return files, nil
}

func nsFileName(ns string) string {
	if ns == "" {
		return "main"
	}
	return strings.ReplaceAll(strings.ToLower(ns), ".", "_")
}

func (g *codegen) finish() []byte {
	// Compute imports from actual usage so generated files never carry
	// unused (or missing) imports.
	var imports []string
	if bytes.Contains(g.out.Bytes(), []byte("tl.")) {
		imports = append(imports, "\t\"github.com/Skryldev/suromesh/tl\"")
	}
	if bytes.Contains(g.out.Bytes(), []byte("fmt.")) {
		imports = append(imports, "\t\"fmt\"")
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by suromesh cmd/tlgen. DO NOT EDIT.\n")
	fmt.Fprintf(&b, "// Schema: api.tl (LAYER %d)", g.opt.Layer)
	for _, s := range g.opt.SchemaSHA {
		if s != "" {
			fmt.Fprintf(&b, " sha256:%s", s)
		}
	}
	b.WriteString("\n\npackage " + g.opt.Package + "\n")
	if len(imports) > 0 {
		b.WriteString("\nimport (\n")
		b.WriteString(strings.Join(imports, "\n"))
		b.WriteString("\n)\n")
	}
	b.WriteString("\n")
	b.Write(g.out.Bytes())

	formatted, err := format.Source(b.Bytes())
	if err != nil {
		// Keep the source in the panic so the generator itself can be
		// fixed; never emit malformed output silently.
		panic(fmt.Sprintf("tlgen: generated invalid Go: %v\n%.600s", err, b.Bytes()))
	}
	return formatted
}

// ---- interfaces ---------------------------------------------------------

func (g *codegen) genInterfaces() error {
	for _, at := range g.sch.AbstractTypes() {
		names := make([]string, 0, len(at.Ctors))
		for _, c := range at.Ctors {
			names = append(names, c.Name+"#"+fmt.Sprintf("%08x", c.ID))
		}
		iface := goInterfaceName(splitQualified(at.Key))
		fmt.Fprintf(g.out, "// %s is the abstract TL type %s (%s).\ntype %s interface{ tl.Object }\n\n",
			iface, at.Key, strings.Join(names, ", "), iface)
	}
	return nil
}

// ---- common -------------------------------------------------------------

func (g *codegen) genCommon() error {
	fmt.Fprintf(g.out, "// Layer is the negotiated TL layer of the source schema.\nconst Layer = %d\n\n", g.opt.Layer)
	g.out.WriteString("func init() { tl.SetDispatchHook(DecodeObjectAfterID) }\n\n")
	g.out.WriteString(`// readObject reads a constructor ID and decodes the object it introduces.
// On an unknown constructor it rewinds to the element start, mirroring the
// reference implementation's TypeNotFoundError positioning behavior.
func readObject(r *tl.Reader) (tl.Object, error) {
	id, err := r.ReadUint32()
	if err != nil {
		return nil, err
	}
	obj, err := DecodeObjectAfterID(id, r)
	if err != nil && tl.IsUnknownConstructor(err) {
		r.Seek(-4)
	}
	return obj, err
}

// DecodeObjectAfterID dispatches on an already-read constructor ID.
`)
	// Manual core cases first, then every generated constructor, sorted by ID
	// for deterministic (and binary-search-friendly) output.
	type entry struct {
		id   uint32
		body string
	}
	var entries []entry
	// Manual core constructors delegate to package tl.
	for id := range manualIDs {
		var body string
		switch id {
		case 0x3072cfa1:
			body = `b, err := tl.DecodeGzipPackedBody(r)
		if err != nil {
			return nil, err
		}
		return &tl.GzipPacked{Data: b}, nil`
		case 0x73f1f8dc:
			body = `return tl.DecodeMessageContainerBody(r)`
		case 0xf35c6d01:
			body = `return tl.DecodeRpcResultBody(r)`
		case 0x2144ca19:
			body = `return tl.DecodeRpcErrorBody(r)`
		}
		entries = append(entries, entry{id, body})
	}
	for _, d := range g.sch.Types {
		entries = append(entries, entry{d.ID, fmt.Sprintf("return decode%sBody(r)", d.GoName)})
	}
	for _, d := range g.sch.Functions {
		entries = append(entries, entry{d.ID, fmt.Sprintf("return decode%sBody(r)", d.GoName)})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].id < entries[j].id })
	g.out.WriteString("func DecodeObjectAfterID(id uint32, r *tl.Reader) (tl.Object, error) {\n\tswitch id {\n")
	for _, e := range entries {
		fmt.Fprintf(g.out, "\tcase %#08x:\n\t\t%s\n", e.id, e.body)
	}
	g.out.WriteString("\tdefault:\n\t\treturn nil, &tl.UnknownConstructorError{ID: id, Remaining: r.Unread()}\n\t}\n}\n")

	// Registry index: every ID the dispatch switch handles.
	g.out.WriteString("\n// constructorIDs lists every constructor ID handled by DecodeObjectAfterID,\n// sorted ascending. It exists for registry-compatibility tests.\n")
	g.out.WriteString("func constructorIDs() []uint32 {\n\treturn []uint32{\n")
	for _, e := range entries {
		fmt.Fprintf(g.out, "\t\t%#08x,\n", e.id)
	}
	g.out.WriteString("\t}\n}\n\n// ConstructorIDs exposes the sorted registry index.\nfunc ConstructorIDs() []uint32 { return constructorIDs() }\n")
	return nil
}

// ---- definitions ---------------------------------------------------------

func (g *codegen) genDef(d *Def) error {
	fields := nonFlagArgs(d)
	fmt.Fprintf(g.out, "// %s represents %s#%08x (result: %s; schema line %d).\n",
		d.GoName, d.Qualified(), d.ID, d.Result.Qualified(), d.Line)
	fmt.Fprintf(g.out, "type %s struct {\n", d.GoName)
	for _, a := range fields {
		typ, err := g.goFieldType(a.Type, a.FlagWord != "")
		if err != nil {
			return fmt.Errorf("%s: %w", d, err)
		}
		fmt.Fprintf(g.out, "\t%s %s\n", a.GoName, typ)
	}
	g.out.WriteString("}\n\n")

	fmt.Fprintf(g.out, "// CtorID implements tl.Object.\nfunc (*%s) CtorID() uint32 { return %#08x }\n\n", d.GoName, d.ID)
	fmt.Fprintf(g.out, "// Encode implements tl.Object.\nfunc (x *%s) Encode(w *tl.Writer) error {\n\tx.writeCtor(w)\n\treturn x.encodeBody(w)\n}\n\n", d.GoName)
	fmt.Fprintf(g.out, "func (x *%s) writeCtor(w *tl.Writer) { w.PutUint32(%#08x) }\n\n", d.GoName, d.ID)
	if d.Kind == KindFunction {
		fmt.Fprintf(g.out, "// IsRequest implements tl.Request.\nfunc (*%s) IsRequest() {}\n\n", d.GoName)
	}
	fmt.Fprintf(g.out, "func (x *%s) encodeBody(w *tl.Writer) error {\n", d.GoName)
	if err := g.genEncodeBody(d); err != nil {
		return err
	}
	g.out.WriteString("}\n\n")

	fmt.Fprintf(g.out, "// Decode%s decodes a full %s including its constructor ID.\nfunc Decode%s(r *tl.Reader) (*%s, error) {\n\tid, err := r.ReadUint32()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif id != %#08x {\n\t\treturn nil, &tl.ConstructorMismatchError{Got: id, Want: %#08x}\n\t}\n\treturn decode%sBody(r)\n}\n\n",
		d.GoName, d.Qualified(), d.GoName, d.GoName, d.ID, d.ID, d.GoName)
	fmt.Fprintf(g.out, "func decode%sBody(r *tl.Reader) (*%s, error) {\n", d.GoName, d.GoName)
	if err := g.genDecodeBody(d); err != nil {
		return err
	}
	g.out.WriteString("}\n\n")
	return nil
}

func nonFlagArgs(d *Def) []*Arg {
	var out []*Arg
	for _, a := range d.Args {
		if a.Type.Kind == KindFlagWord {
			continue
		}
		out = append(out, a)
	}
	return out
}

func (g *codegen) flagWords(d *Def) []*Arg {
	var out []*Arg
	for _, a := range d.Args {
		if a.Type.Kind == KindFlagWord {
			out = append(out, a)
		}
	}
	return out
}

// goFieldType maps a TypeRef to its Go type. optional selects pointer/slice
// presence encoding.
func (g *codegen) goFieldType(t TypeRef, optional bool) (string, error) {
	switch t.Kind {
	case KindFlagTrue:
		return "bool", nil
	case KindBoxedGeneric:
		return "tl.Request", nil
	case KindVector:
		elem, err := g.goFieldType(*t.Elem, false)
		if err != nil {
			return "", err
		}
		if optional {
			return "[]" + elem, nil // nil slice = absent
		}
		return "[]" + elem, nil
	case KindNamed:
		// Bare elements reference the concrete struct (no ctor on the wire).
		if t.Bare && !t.Primitive() {
			cn, err := g.goConcreteType(t)
			if err != nil {
				return "", err
			}
			return cn, nil
		}
		base, err := g.goBaseType(t)
		if err != nil {
			return "", err
		}
		switch base {
		case "string", "int32", "int64", "float64", "float32", "bool":
			if optional {
				return "*" + base, nil
			}
			return base, nil
		case "[16]byte", "[32]byte":
			if optional {
				return "*" + base, nil
			}
			return base, nil
		default: // []byte or interface
			return base, nil
		}
	case KindGenericRef, KindFlagWord:
		return "", fmt.Errorf("unsupported field type kind %d", t.Kind)
	}
	return "", fmt.Errorf("unknown type kind %d", t.Kind)
}

// goBaseType maps a non-vector type reference to its Go type; []byte and
// interface types carry their own presence semantics.
func (g *codegen) goBaseType(t TypeRef) (string, error) {
	switch t.Qualified() {
	case "int":
		return "int32", nil
	case "long":
		return "int64", nil
	case "double":
		return "float64", nil
	case "float":
		return "float32", nil
	case "string":
		return "string", nil
	case "bytes":
		return "[]byte", nil
	case "int128":
		return "[16]byte", nil
	case "int256":
		return "[32]byte", nil
	case "Bool":
		return "bool", nil
	case "true":
		return "bool", nil
	}
	iface := goInterfaceName(t.NS, t.Name)
	return iface, nil
}

// goConcreteType returns the concrete struct type for a bare element.
func (g *codegen) goConcreteType(t TypeRef) (string, error) {
	d, ok := g.byName[t.Qualified()]
	if !ok {
		return "", fmt.Errorf("bare reference to unknown type %q", t.Qualified())
	}
	return d.GoName, nil
}
